DROP TABLE IF EXISTS `lead`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lead` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `whatsapp` varchar(20) DEFAULT NULL,
  `email` varchar(120) DEFAULT NULL,
  `course_interest_id` int DEFAULT NULL,
  `lead_source` varchar(50) DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `quoted_amount` float DEFAULT NULL,
  `last_contact_date` date DEFAULT NULL,
  `next_followup_date` date DEFAULT NULL,
  `followup_type` varchar(20) DEFAULT NULL,
  `comments` text,
  `created_at` datetime DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `followup_time` time DEFAULT NULL,
  `followup_priority` varchar(20) DEFAULT NULL,
  `assigned_to` int DEFAULT NULL,
  `added_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `course_interest_id` (`course_interest_id`),
  KEY `created_by_id` (`created_by_id`),
  KEY `added_by` (`added_by`),
  KEY `assigned_to` (`assigned_to`)
) ENGINE=MyISAM AUTO_INCREMENT=5782 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

